''','''
  // Must be registered before express.json(): the signature is over the raw body.
  app.post("/webhooks/payments", express.raw({ type: "*/*", limit: "100kb" }), paymentWebhook);

  app.use(express.json());
''',1)
s=s.replace('export function createApp()','''const eventStatus = { "charge.succeeded": "paid", "charge.failed": "failed", "charge.refunded": "refunded" } as const;
// Within the same second, a later lifecycle stage wins over an earlier one.
const statusRank = { paid: 1, failed: 1, refunded: 2 } as const;

function validSignature(raw: Buffer, header: unknown) {
  if (typeof header !== "string") return false;
  const expected = createHmac("sha256", webhookSecret).update(raw).digest();
  const given = Buffer.from(header, "hex");
  return given.length === expected.length && timingSafeEqual(given, expected);
}

async function paymentWebhook(req: Request, res: Response) {
  const raw = req.body;
  if (!Buffer.isBuffer(raw) || !validSignature(raw, req.headers["provider-signature"])) {
    return sendError(res, 401, "invalid_signature", "Invalid webhook signature");
  }
  let event: { id?: unknown; type?: unknown; paymentId?: unknown; created?: unknown };
  try {
    event = JSON.parse(raw.toString("utf8"));
  } catch {
    return sendError(res, 400, "invalid_body", "Body must be JSON");
  }
  const { id, type, paymentId, created } = event;
  if (
    typeof id !== "string" || typeof paymentId !== "string" ||
    typeof type !== "string" || !Object.hasOwn(eventStatus, type) ||
    typeof created !== "number" || !Number.isFinite(created)
  ) {
    return sendError(res, 400, "invalid_event", "Invalid webhook event");
  }
  const status = eventStatus[type as keyof typeof eventStatus];

  const client = await pool.connect();
  try {
    await client.query("begin");
    const dedupe = await client.query(
      "insert into payment_webhook_events (id) values ($1) on conflict do nothing",
      [id],
    );
    if (dedupe.rowCount === 0) {
      await client.query("rollback");
      return res.json({ ok: true, duplicate: true });
    }
    const { rows } = await client.query(
      "select id, status, payment_event_at from orders where payment_id = $1 for update",
      [paymentId],
    );
    if (rows.length === 0) {
      // Not recorded, so the provider's retry can succeed once the order has its payment id.
      await client.query("rollback");
      return sendError(res, 404, "order_not_found", "No order for this payment");
    }
    for (const order of rows) {
      const at = order.payment_event_at ? order.payment_event_at.getTime() / 1000 : null;
      const prev = statusRank[order.status as keyof typeof statusRank] ?? 0;
      const newer = at === null || created > at || (created === at && statusRank[status] > prev);
      if (newer) {
        await client.query(
          "update orders set status = $1, payment_event_at = to_timestamp($2) where id = $3",
          [status, created, order.id],
        );
      }
    }
    await client.query("commit");
    res.json({ ok: true });
  } catch (err) {
    await client.query("rollback").catch(() => {});
    throw err;
  } finally {
    client.release();
  }
}

export function createApp()''',1)
open(p,'w').write(s)
EOF
sed -n 60,200p test/app.test.ts; cat db/seed.sql | grep -i orders

sed -n 10,20p db/seed.sql && cat >> test/app.test.ts <<'EOF'

async function webhook(event: object, secret = webhookSecret) {
  const body = JSON.stringify(event);
  const sig = createHmac("sha256", secret).update(body).digest("hex");
  return fetch(`${base}/webhooks/payments`, { method: "POST", headers: { "provider-signature": sig, "content-type": "application/json" }, body });
}

test("payment webhooks: signature, status mapping, duplicates and out-of-order events", async () => {
  const { rows: [order] } = await pool.query("insert into orders (user_id, total_cents, payment_id) values (1, 100, 'pay_wh') returning id");
  const status = async () => (await pool.query("select status from orders where id = $1", [order.id])).rows[0].status;

  assert.equal((await webhook({ id: "e0", type: "charge.succeeded", paymentId: "pay_wh", created: 1000 }, "wrong")).status, 401);
  assert.equal(await status(), "pending");

  assert.equal((await webhook({ id: "e1", type: "charge.succeeded", paymentId: "pay_wh", created: 1000 })).status, 200);
  assert.equal(await status(), "paid");
  assert.equal((await webhook({ id: "e3", type: "charge.refunded", paymentId: "pay_wh", created: 3000 })).status, 200);
  assert.equal(await status(), "refunded");
  // late delivery of an older event, and a redelivery
  await webhook({ id: "e2", type: "charge.failed", paymentId: "pay_wh", created: 2000 });
  await webhook({ id: "e1", type: "charge.succeeded", paymentId: "pay_wh", created: 1000 });
  assert.equal(await status(), "refunded");

  assert.equal((await webhook({ id: "e4", type: "charge.succeeded", paymentId: "pay_nope", created: 1 })).status, 404);
  assert.equal((await webhook({ id: "e5", type: "bogus", paymentId: "pay_wh", created: 1 })).status, 400);
});
EOF
